#!/usr/bin/env python3
from pathlib import Path
import datetime,hashlib,json,math,statistics
E=Path('$EXPERIMENT');R=E/'downstream/arm64';OUT=R/'analysis';OUT.mkdir(exist_ok=True);assert not (OUT/'measurement-review.json').exists()
def load(p):return json.loads(Path(p).read_text())
def sha(p):
 with Path(p).open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
def save(p,j):
 with p.open('x') as f:json.dump(j,f,indent=2);f.write(chr(10))
def close(a,b):assert math.isclose(a,b,rel_tol=1e-12,abs_tol=1e-12),(a,b)
phases=load(R/'control/timing-complete.json')['phases'];totals={k:0 for k in ['measured_samples','warmups','measured_processes','warmup_processes']};audit_rows=[];rows=[];outliers=[];triggers=[]
for phase in phases:
 label=phase['group']+'-'+phase['phase'];path=R/'audits-01'/(label+'.json');audit=load(path);assert audit['passed'] and audit['all_output_bytes_verified'] and audit['resource_metrics_reconciled'];relative=str(path.relative_to(E));audit_rows.append({'group':phase['group'],'phase':phase['phase'],'receipt':relative,**{k:audit[k] for k in totals}})
 for k in totals:totals[k]+=audit[k]
 for case,result in audit['recomputed'].items():
  pairs=result['pairs'];assert len(pairs)==6 and [p['round'] for p in pairs]==list(range(1,7));absolute={};deltas={};medians={};ranges={}
  for metric,field in [('elapsed','elapsed_ns'),('cpu','cpu_seconds'),('rss','peak_rss_bytes')]:
   values=[]
   for pair in pairs:
    b=pair['B'][field];c=pair['C'][field];value=(c/b-1)*100 if b else None
    if value is None:assert pair[metric+'_change_pct'] is None
    else:close(value,pair[metric+'_change_pct']);values.append(value)
   medians[metric]=statistics.median(values) if values else None;ranges[metric]=[min(values),max(values)] if values else None
   if values:close(medians[metric],result['paired_change_medians'][metric]);[close(x,y) for x,y in zip(ranges[metric],result['paired_change_ranges'][metric])]
   absolute[field]={v:{'median':statistics.median(p[v][field] for p in pairs),'min':min(p[v][field] for p in pairs),'max':max(p[v][field] for p in pairs)} for v in ['B','C']};deltas[field]=statistics.median(p['C'][field]-p['B'][field] for p in pairs)
  row={'platform':'arm64','group':phase['group'],'phase':phase['phase'],'case':case,'n':6,'audit_receipt':relative,'pairs':pairs,'paired_change_medians':medians,'paired_change_ranges':ranges,'absolute':absolute,'paired_absolute_delta_medians':deltas,'positive_elapsed_pairs':sum(p['elapsed_change_pct']>0 for p in pairs)};rows.append(row)
  if phase['phase']=='primary' and (medians['elapsed']>5 or medians['rss']>5):triggers.append({'group':phase['group'],'case':case,'elapsed_median_pct':medians['elapsed'],'cpu_median_pct':medians['cpu'],'rss_median_pct':medians['rss']})
  for pair in pairs:
   above={k:pair[k+'_change_pct'] for k in ['elapsed','cpu','rss'] if pair[k+'_change_pct'] is not None and pair[k+'_change_pct']>5}
   if above:outliers.append({'group':phase['group'],'phase':phase['phase'],'case':case,'round':pair['round'],'above_five_pct':above})
assert totals=={'measured_samples':312,'warmups':52,'measured_processes':372,'warmup_processes':62};assert len(rows)==26 and sum(len(r['pairs']) for r in rows)==156
assert len(triggers)==1 and triggers[0]['case']=='mixed-disjoint-1000'
identity=R/'metadata/postmeasurement-identity.json';assert load(identity)['passed'];save(R/'audits-01/summary.json',{'passed':True,'audit_rows':audit_rows,'totals':totals,'all_phases_independently_audited':True})
review={'passed':True,'reviewed_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'platform':'arm64','audit_summary':'downstream/arm64/audits-01/summary.json','audit_totals':totals,'summary_rows':len(rows),'pairs':sum(r['n'] for r in rows),'rows':rows,'tiny_case_classifications':{'mixed-disjoint-1000':'Primary elapsed paired median +5.72% and CPU +6.07%; fixed follow-up +2.12% elapsed and +1.76% CPU, with broad signed spreads in both phases. No repeated above5% median regression; retain the primary trigger and classify direction as inconclusive.'},'method_limits':['Elapsed includes process launch, input/output and completion; CPU and RSS come from wait4 for the exact child.','Split-family observations sum elapsed/CPU and use maximum constituent-process RSS, not combined simultaneous RSS.','Small-input wait4 peak RSS can include a pre-exec parent high-water floor. Identical roughly21.7-23.0MiB B/C values in the1,000-entry control do not establish equal CLI allocations.','No sample was removed or pooled. The required fixed follow-up is separate, and individual above5% observations remain recorded.','Native ARM64 Linux runs through OrbStack; these results do not establish bare-metal Linux behavior.'],'postmeasurement_identity':{'passed':True,'runtime_receipt':str(identity.relative_to(E)),'runtime_receipt_sha256':sha(identity),'complete_source_inventories_match':True,'all_five_dependency_workspaces_clean_at_exact_remote_pins':True,'compiler_binaries_and_linked_runtime_hashes_match':True,'all_bound_hashes_verified_by_all_four_audits':True},'primary_triggers':triggers,'all_above_five_observations':outliers,'no_new_measurements':True};save(OUT/'measurement-review.json',review)
lines=['# ARM64 Linux matched integration review','',f'All four independent audits passed: {totals["measured_samples"]} measured observations, {totals["warmups"]} excluded warmups, {totals["measured_processes"]} measured child processes and {totals["warmup_processes"]} warmup processes. There are26 phase-separated summaries and156 pairs.','', 'Only the1,000-entry disjoint case triggered the prescribed follow-up: +5.72% elapsed/+6.07% CPU initially, then +2.12%/+1.76%. Its elapsed ranges cross zero widely in both phases (−10.85…+20.13%, then−12.39…+10.45%). No elapsed or RSS paired-median regression above5% repeated. All observations remain retained.','', 'Original million-entry elapsed paired medians range from−1.24% to+3.50%; RSS from−4.47% to+0.09%. Range-derived input is+3.50% elapsed/+3.50% CPU and+0.08% RSS. The1,000,002-entry sparse input is+0.89% elapsed/+0.88% CPU and+0.02% RSS, with broad signed timing spread. These small changes should not be presented as general throughput gains.','', 'Small-input RSS is limited by the Linux pre-exec parent high-water floor; equal RSS does not prove equal allocations.','', '| Group / phase | Case | B elapsed ms | C elapsed ms | Paired elapsed % [min,max] | Paired CPU % [min,max] | B RSS MiB | C RSS MiB | Paired RSS % [min,max] |','| --- | --- | ---: | ---: | --- | --- | ---: | ---: | --- |']
for row in rows:
 def effect(k):
  v=row['paired_change_medians'][k];span=row['paired_change_ranges'][k]
  return 'unavailable' if v is None else f'{v:+.3f} [{span[0]:+.3f}, {span[1]:+.3f}]'
 ab=row['absolute'];lines.append(f'| {row["group"]} / {row["phase"]} | {row["case"]} | {ab["elapsed_ns"]["B"]["median"]/1e6:.4f} | {ab["elapsed_ns"]["C"]["median"]/1e6:.4f} | {effect("elapsed")} | {effect("cpu")} | {ab["peak_rss_bytes"]["B"]["median"]/1024**2:.4f} | {ab["peak_rss_bytes"]["C"]["median"]/1024**2:.4f} | {effect("rss")} |')
lines+=['','All individual positive changes above5% (elapsed, CPU or RSS) are listed without removal in `measurement-review.json`; these individual observations are distinct from the paired-median follow-up criterion.','', 'Postmeasurement checks verified both complete source inventories, all five ordinary/test/floor dependency workspaces, compiler and binary/runtime hashes, and zero memory/OOM events. The container is stopped and preserved.']
(OUT/'measurement-review.md').write_text('\n'.join(lines)+'\n')
index={'passed':True,'platform':'arm64','audit_rows':audit_rows,'audit_totals':totals,'measurement_review':str((OUT/'measurement-review.json').relative_to(E)),'qualification_gate':'downstream/arm64/control/qualification-gate.json','bindings':'downstream/arm64/control/premeasurement.json','sources':{'B':'control/cidrmerge-baseline-freeze.json','C':'control/cidrmerge-candidate-freeze.json'},'publication':'control/upstream-publication.json','qualification':{'B':'downstream/arm64/control/B-qualification/summary.json','C':'downstream/arm64/control/C-qualification/summary.json','floor_C':'downstream/arm64/floor-6.2.4/control/C-qualification/summary.json','cli_differential':'downstream/arm64/differential-01/summary.json','io_differential':'downstream/arm64/io-differential-01/summary.json','final_validation':'downstream/arm64/final-validation-01/summary.json'},'environment':{'B':'downstream/arm64/control/B-qualification/environment.json','C':'downstream/arm64/control/C-qualification/environment.json','preparation_B':'downstream/arm64/control/B-preparation.json','preparation_C':'downstream/arm64/control/C-preparation.json'},'artifacts':{v:'downstream/arm64/metadata/'+v+'-ordinary.json' for v in ['B','C']},'postmeasurement_identity':str(identity.relative_to(E)),'container_final':'downstream/arm64/control/container-stopped-final.json','preserved_failures':{'product_failures':[],'qualification_or_timing_failures':[],'notes':['Optional file utility absent in cached image was detected before builds; readelf used for architecture metadata without installing anything.','All intentional negative-control observations are preserved under downstream/harness-controls-macos-01,-02, binding-controls-macos-01 and arm64/control/downstream-harness-controls-linux-01,-02.']},'no_new_measurements':True};save(OUT/'report-index.json',index)
print(json.dumps({'passed':True,'rows':len(rows),'pairs':sum(x['n'] for x in rows),'totals':totals,'primary_triggers':triggers,'individual_above_five_observations':len(outliers)}),flush=True)
